dir:










































  &DefaultButton;




function dir$dmkc(p){
  this.constructor(p);
}
dir$dmkc.prototype = new DirEvent();
dir$dmkc.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmkc.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmkcDisabledMasterField(p, g);

}

function dir$dmkcDisabledMasterField(p, g){

  if(p.valForm('ma_kc').trim() != '')
  {
    p.setDisabled('ma_kc', true);
  }
  else
  {
    p.setDisabled('ma_kc', false);
  }
}









declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã khoảng cách đã tồn tại' else N'Distance code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã khoảng cách đã tồn tại' else N'Distance code already exists' end
